            if 0 <= nr < h and 0 <= nc < w:
                yield nr, nc

    # Connected components of each non-background color.
    seen = [[False] * w for _ in range(h)]
    comps_by_color = defaultdict(list)

    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or seen[r][c]:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            touches_border = False
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                if x == 0 or x == h - 1 or y == 0 or y == w - 1:
                    touches_border = True
                for nx, ny in neighbors(x, y):
                    if not seen[nx][ny] and grid[nx][ny] == color:
                        seen[nx][ny] = True
                        q.append((nx, ny))
            comps_by_color[color].append((cells, touches_border))

    # Source: a border singleton whose color appears elsewhere too.
    source = None
    for color, comps in comps_by_color.items():
        if len(comps) < 2:
            continue
        for cells, touches_border in comps:
            if len(cells) == 1 and touches_border:
                source = cells[0]
                break
        if source is not None:
            break

    # Fallbacks if needed.
    if source is None:
        for color, comps in comps_by_color.items():
            for cells, touches_border in comps:
                if len(cells) == 1 and touches_border:
                    source = cells[0]
                    break
            if source is not None:
                break

